const root=document.querySelector('#app'),qs=new URLSearchParams(location.search)
const asset=name=>new URL(`./assets/${name}`,document.baseURI).href
let mode=qs.get('mode')||'start',session=null,teams=[],players=[],votes=[],team=null,me=null,expanded=null
const phases=['elect','journey','story','opening_question','opening_cloud','needs','design_brief','rules','example','cap_vote1','cap_talk1','commit_vote1','commit_talk1','resource_check','cap_vote2','cap_talk2','commit_vote2','commit_talk2','designed','event','predict','consequence','principle','complete']
const costs={ambient:[3,2],wayfinding:[2,2],meds:[3,3],command:[5,5]}
const needMap={ambient:['UNDERSTAND','CONNECT'],wayfinding:['MOVE','TRUST'],meds:['UNDERSTAND','CONNECT'],command:['MOVE','CONNECT']}
const q=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])),S=()=>game.settings[0]

// Stable delegated handler: survives every re-render of the design-choice screen.
document.addEventListener('click',event=>{
 const button=event.target.closest?.('[data-design-index]');
 if(!button)return;
 event.preventDefault();event.stopPropagation();
 const index=Number(button.dataset.designIndex),capabilityId=button.dataset.capabilityId||soloState?.pendingCapability;
 const choices=capabilityId?soloCommitmentOptions(capabilityId):[];
 const choice=choices[index];
   const architect=choice?architectureChoice(capabilityId,choice.id):null;
 if(!capabilityId||!Number.isInteger(index)||!choice){
  console.error('Design selection unavailable',{capabilityId,index,choices});
  const error=q('#designChoiceError');if(error){error.hidden=false;error.textContent=`Design selection unavailable: ${capabilityId||'missing capability'} / choice ${Number.isInteger(index)?index:'missing'}.`}
  return;
 }
 button.disabled=true;
 try{soloSaveActivation(capabilityId,choice,index)}catch(error){
  button.disabled=false;console.error('Design selection failed',error);
  const message=q('#designChoiceError');if(message){message.hidden=false;message.textContent=`Unable to continue: ${error?.message||'unknown error'}`}
 }
});
const layout=x=>root.innerHTML=`<div class="top"><b>ARTHUR: BY DESIGN</b><span>${session?'ROOM '+E(session.code):'1.0'}</span></div><main class="shell">${x}</main>`
const go=(m,x={})=>location.search=new URLSearchParams({mode:m,...x})
const tp=t=>players.filter(p=>p.team_id===t.id),ready=t=>!!t.facilitator_player_id||t.status==='majority'

function isPhone(){return matchMedia('(max-width:720px)').matches||/Android|iPhone|iPod/i.test(navigator.userAgent)}
function soloRegistrationUrl(){let u=new URL(location.href);u.search='';u.searchParams.set('mode','solo-register');return u.toString()}
function frontDoor(){layout(`<section class="front-door"><div class="eyebrow">ARTHUR · AI · ARCHITECTURE</div><h1>ARTHUR:<br>BY DESIGN</h1><p class="door-thesis">AI changes what care can do. Design determines what Arthur can use.</p><div class="door-principles"><article><span>UTILITAS</span><b>USEFUL</b><p>Can Arthur do what Arthur needs?</p></article><article><span>FIRMITAS</span><b>RESILIENT</b><p>Will the design still work when plans change?</p></article><article><span>VENUSTAS</span><b>HUMAN</b><p>Does Arthur retain dignity, confidence and independence?</p></article></div><div class="door-actions"><button id="f">FACILITATE A SESSION<small>Create the room and guide the shared experience</small></button><button id="p">JOIN A TABLE<small>Enter your workshop room from this device</small></button><button id="solo" class="explore">EXPLORE ON MY OWN<small>Make the decisions and see the design consequences</small></button></div></section>`);q('#f').onclick=()=>go('facilitator');q('#p').onclick=()=>go('player');q('#solo').onclick=()=>isPhone()?soloRegistration():soloPhoneHandoff()}
function soloPhoneHandoff(){let url=soloRegistrationUrl();layout(`<section class="phone-handoff"><div class="eyebrow">EXPLORE ON MY OWN</div><h1>CONTINUE ON YOUR PHONE</h1><p>Scan the QR code to make Arthur's design decisions on your phone.</p><div class="qr-wrap">${qr(url)}</div><p><b>Or continue here.</b></p><div class="or-divider">YOUR CHOICE</div><button id="continueHere">CONTINUE ON THIS DEVICE</button><button id="backHome" class="ghost">BACK</button></section>`);q('#continueHere').onclick=()=>soloRegistration();q('#backHome').onclick=()=>frontDoor()}
function soloRegistration(){layout(registrationHTML());q('#participantRegistration').onsubmit=async e=>{e.preventDefault();let d=readRegistration(),err=q('#registrationError');if(!validEmail(d.email)){err.textContent='Enter a valid email address.';return}if(!d.role_type){err.textContent='Select the perspective you bring.';return}err.textContent='';let btn=e.submitter;btn.disabled=true;btn.textContent='CREATING YOUR EXPERIENCE...';let identity=await createSoloIdentity(d);localStorage.setItem('abd10-participant',JSON.stringify(identity));localStorage.removeItem(SOLO_KEY);soloState=defaultSolo();soloState.participantId=identity.player_id;soloState.sessionId=identity.session_id;soloState.participantEmail=d.email;soloState.participantRole=d.role_type;saveSolo();go('solo')}}
async function createSoloIdentity(d){let fallback={session_id:crypto.randomUUID(),player_id:crypto.randomUUID(),local_only:true};if(!configured)return fallback;try{let code='S'+Math.random().toString(36).slice(2,8).toUpperCase(),sr=await supabase.from('sessions').insert({code,screen:'solo',phase:'solo',status:'active'}).select().single();if(sr.error)throw sr.error;let pr=await supabase.from('players').insert({session_id:sr.data.id,team_id:null,initials:derivedInitials(d.email),email:d.email,role_type:d.role_type,imagery_consent:d.imagery_consent,imagery_consent_at:d.imagery_consent?new Date().toISOString():null,experience_mode:'solo'}).select().single();if(pr.error)throw pr.error;return{session_id:sr.data.id,player_id:pr.data.id,local_only:false}}catch(error){console.warn('Solo registration stored locally until sync is available',error);return fallback}}
async function savePlayerResponse(question_id,response_text,round_id='leave_well'){let raw=localStorage.getItem('abd10-participant');if(!raw||!configured)return;try{let x=JSON.parse(raw);if(x.local_only)return;await supabase.from('player_responses').upsert({session_id:x.session_id,player_id:x.player_id,round_id,question_id,response_text},{onConflict:'player_id,question_id'})}catch(error){console.warn('Response sync delayed',error)}}
function start(){frontDoor()}
function error(x){layout(`<div class="error">${E(x)}</div>`)}
async function refresh(){let[t,p,v]=await Promise.all([supabase.from('teams').select('*').eq('session_id',session.id).order('table_name'),supabase.from('players').select('*').eq('session_id',session.id),supabase.from('votes').select('*').eq('session_id',session.id).order('created_at')]);teams=t.data||[];players=p.data||[];votes=v.data||[];if(team)team=teams.find(x=>x.id===team.id)||team;if(me)me=players.find(x=>x.id===me.id)||me}
async function load(code){let r=await supabase.from('sessions').select('*').eq('code',code.toUpperCase()).maybeSingle();if(!r.data)throw Error(r.error?.message||'Room not found');session=r.data;await refresh();supabase.channel('r'+session.id).on('postgres_changes',{event:'*',schema:'public',table:'sessions',filter:`id=eq.${session.id}`},async p=>{session=p.new;await refresh();render()}).on('postgres_changes',{event:'*',schema:'public',table:'teams',filter:`session_id=eq.${session.id}`},async()=>{await refresh();render()}).on('postgres_changes',{event:'*',schema:'public',table:'players',filter:`session_id=eq.${session.id}`},async()=>{await refresh();render()}).on('postgres_changes',{event:'*',schema:'public',table:'votes',filter:`session_id=eq.${session.id}`},async()=>{await refresh();render()}).subscribe();render()}
async function create(){if(!configured)return error('Supabase is not configured.');let code=Math.random().toString(36).slice(2,6).toUpperCase(),r=await supabase.from('sessions').insert({code,stage_index:0,phase:'elect'}).select().single();if(r.error)return error(r.error.message);go('facilitator',{room:r.data.code})}
function joinUrl(){let u=new URL(location.href);u.search='';u.searchParams.set('mode','player');u.searchParams.set('room',session.code);return u.toString()}
function qr(text){let z=new QRCode(-1,L.M);z.addData(text);z.make();let n=z.getModuleCount(),d='',m=4;for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(z.isDark(r,c))d+=`M${c+m} ${r+m}h1v1h-1z`;return`<svg viewBox="0 0 ${n+8} ${n+8}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="white"/><path d="${d}" fill="#000"/></svg>`}

async function facilitator(){let room=qs.get('room');if(!room){layout(`<h1>Create the room.</h1><button id="create">CREATE SESSION</button>`);q('#create').onclick=create;return}try{await load(room)}catch(e){error(e.message)}}
function investments(t=team){return(t?.investments||[]).filter(i=>i.stage===S().id)}
function remaining(t=team){let x=investments(t);return{capital:7-x.reduce((n,i)=>n+i.capital,0),change:6-x.reduce((n,i)=>n+i.change,0)}}
function bars(t=team){let r=remaining(t);return`<div class="bars"><div><b>CAPITAL</b><span>${'●'.repeat(r.capital)}${'○'.repeat(7-r.capital)}</span><strong>${r.capital}</strong></div><div><b>CHANGE</b><span>${'●'.repeat(r.change)}${'○'.repeat(6-r.change)}</span><strong>${r.change}</strong></div></div>`}
function rules(){return`<section class="rules"><div class="eyebrow">THE ACTIVATION CHALLENGE</div><h1>DESIGN FOR WHAT COMES NEXT.<br>ACTIVATE WHAT MATTERS NOW.</h1><p class="rules-intro">A future-ready hospital should be able to adapt as care, technology and Arthur’s needs evolve. Your table is not deciding what the hospital will never do. Your table is deciding what the hospital can responsibly activate first.</p><div class="budget"><div><strong>7</strong><b>CAPITAL</b><span>Implementation capacity to fund, build, integrate and enable capabilities.</span></div><div><strong>6</strong><b>CHANGE</b><span>Organizational capacity for workflow, training, governance, ownership and new ways of operating.</span></div></div><div class="rules-round"><b>IN THIS ROUND</b><span>Explore four capabilities. Activate up to two. Design what makes each usable for Arthur. Then see whether the design adapts when conditions change.</span></div><div class="callout"><b>A CAPABILITY MUST FIT BOTH.</b><br>The hospital may be able to afford the technology without having enough organizational capacity to make it work.</div></section>`}
function story(){return`<section class="story"><div class="video"><span>VIDEO PLACEHOLDER</span><b>HOSPITAL → HOME</b></div><div><div class="eyebrow">HOSPITAL → HOME</div><h1>ARTHUR IS GOING HOME.</h1><p>A successful surgery got Arthur here.</p><h2>Now the transition begins.</h2><p>Arthur has to understand a new care plan, leave the hospital safely, reconnect with medications and follow-up, and remain confident as conditions change along the way.</p><div class="storyline">THE PROCEDURE IS COMPLETE. ARTHUR’S JOURNEY ISN’T.</div></div></section>`}
function needs(){return`<section class="needs"><div class="eyebrow">LEAVE WELL</div><h1>WHAT DOES ARTHUR NEED TO LEAVE WELL?</h1><div class="needgrid"><article><i>💬✓</i><b>UNDERSTAND</b><p>Arthur needs to understand what happened, medication changes, warning signs and what comes next.</p></article><article><i>⌁●</i><b>MOVE</b><p>Arthur needs to move from bedside into the next setting safely and confidently.</p></article><article><i>●—●</i><b>CONNECT</b><p>Arthur needs the care plan, medications, people and follow-up to stay connected.</p></article><article><i>◇✓</i><b>TRUST</b><p>Arthur needs to know what to do and who will respond as conditions change.</p></article></div><div class="callout"><b>Arthur needs all four.</b> Your table cannot invest everywhere at once. Which capability gives Arthur the strongest transition with the resources available?</div></section>`}
const phaseLabels={journey:'Arthur’s connected care journey',design_brief:'Designing for Arthur',rules:'How the activation challenge works',story:'Meet Arthur',opening_question:'First instinct',opening_cloud:'What the room sees',needs:'What Arthur needs',example:'How to read a capability',cap_vote1:'Explore and vote · Activation 1',cap_talk1:'Pressure-test the first choice',commit_vote1:'Design around the capability',commit_talk1:'Reach the table decision',resource_check:'Is the design strong enough?',cap_vote2:'Explore and vote · Activation 2',cap_talk2:'Pressure-test the supporting choice',commit_vote2:'Design around the capability',commit_talk2:'Reach the table decision',designed:'What your table designed',event:'Conditions change',predict:'Will the design hold?',consequence:'Arthur’s experience',principle:'Firmitas',complete:'Round 1 complete'};
function capabilityLong(c){return{ambient:{arthur:'Arthur leaves with a transition plan built from the actual care conversation.',environment:'A setting that supports privacy, participation and verification.',operations:'A clear owner for reviewing, confirming and carrying the plan forward.',signal:'AI can capture the conversation. Design determines whether Arthur can actually have it.'},wayfinding:{arthur:'Arthur can navigate a changing route with less uncertainty.',environment:'Layered physical, digital and human cues with accessible fallback.',operations:'Owned route content and a reliable response when guidance is not enough.',signal:'A route can be accurate and still be unusable.'},meds:{arthur:'Arthur carries fewer contradictory medication instructions home.',environment:'A transition setting where medication changes can be explained and confirmed.',operations:'Named ownership for resolution, explanation and downstream updates.',signal:'Detection is not resolution.'},command:{arthur:'Arthur experiences fewer disconnected handoffs and unexplained waits.',environment:'Visible transition capacity, routes and alternatives across the hospital.',operations:'Authority, workflow and staffing that can respond to what the system sees.',signal:'Visibility is not capacity. Coordination does not create resources.'}}[c.id]}
function designBrief(){return`<section class="design-brief"><div class="eyebrow">DESIGNING FOR ARTHUR</div><h1>EVERY CAPABILITY CHANGES MORE THAN TECHNOLOGY.</h1><p class="brief-lead">You will explore capabilities your table could activate first. Each choice can change Arthur’s care journey, the work of the people supporting Arthur and the built environment where care happens.</p><div class="brief-grid"><div><b>ARTHUR</b><span>What becomes clearer, safer or more connected in Arthur’s journey?</span></div><div><b>PEOPLE + OPERATIONS</b><span>What changes in workflow, ownership, training and response?</span></div><div><b>BUILT ENVIRONMENT</b><span>What must the environment enable, protect or adapt to?</span></div></div><div class="callout"><b>YOUR ROLE</b><br>Design for the full journey. Then decide what the hospital can responsibly activate first.</div></section>`}
function exampleScreen(){let c=S().capabilities.find(x=>x.id==='ambient'),d=capabilityLong(c);return`<section class="example"><div class="eyebrow">BEFORE YOU CHOOSE</div><h1>HOW TO READ A CAPABILITY</h1><p class="example-intro">You will be presented with four capabilities your table could activate. Every option affects Arthur, people and operations, and the built environment. Let’s look at one.</p><h2 class="example-name">AMBIENT DISCHARGE + HANDOFF</h2><div class="example-grid"><div><b>STRENGTHENS</b><p>Understand + Connect</p></div><div><b>COSTS</b><p>3 Capital · 2 Change</p></div><div><b>FOR ARTHUR</b><p>${E(d.arthur)}</p></div><div><b>BUILT ENVIRONMENT</b><p>${E(d.environment)}</p></div><div><b>OPERATING COMMITMENT</b><p>${E(d.operations)}</p></div><div class="example-signal"><b>DESIGN CONSIDERATION</b><p>${E(d.signal)}</p></div></div><div class="callout">Every capability can be explored this way. On your phone: tap the capability name → explore the long view → return → vote privately.</div></section>`}
function capCards(){return S().capabilities.map(c=>{let[ca,ch]=costs[c.id],d=capabilityLong(c);return`<article><div class="need-card-tags">${needMap[c.id].map(n=>`<span>${n==='UNDERSTAND'?'?':n==='MOVE'?'→':n==='CONNECT'?'∞':'✓'} ${n}</span>`).join('')}</div><h2>${E(c.name)}</h2><div class="cost">${ca} CAPITAL · ${ch} CHANGE</div><p><b>FOR ARTHUR</b><br>${E(d.arthur)}</p><p><b>BUILT ENVIRONMENT</b><br>${E(d.environment)}</p><p><b>OPERATING COMMITMENT</b><br>${E(d.operations)}</p><blockquote>${E(d.signal)}</blockquote></article>`}).join('')}
function tableStatus(){let phase=session.phase,decision=phase.startsWith('cap_')?'capability'+(phase.endsWith('2')?'2':'1'):phase.startsWith('commit_')?'commitment'+(phase.endsWith('2')?'2':'1'):null;return`<section class="table-status"><div class="eyebrow">TABLE STATUS</div>${teams.map(t=>{let joined=tp(t).length,text=`${joined} participant${joined===1?'':'s'} · ready`;if(phase==='elect'){let f=tp(t).find(p=>p.id===t.facilitator_player_id);text=t.status==='majority'?`${joined} joined · majority rule`:f?`${joined} joined · ${E(f.initials)} ready`:`${joined} joined · choosing facilitator`}else if(decision){let n=votes.filter(v=>v.team_id===t.id&&v.stage_id===S().id&&v.decision===decision).length;if(phase.includes('vote'))text=`${n}/${joined} voted`;else{let counts={};votes.filter(v=>v.team_id===t.id&&v.stage_id===S().id&&v.decision===decision).forEach(v=>counts[v.choice]=(counts[v.choice]||0)+1);let paths=Object.values(counts).filter(x=>x>0).length;text=joined===1?'pressure-testing one choice':paths<=1?'table aligned · pressure-testing':'discussing more than one path'}}else if(['resource_check','designed','event','predict','consequence','principle','complete'].includes(phase)){let r=remaining(t);text=`${investments(t).length} of 2 activated · ${r.capital} Capital · ${r.change} Change`}return`<span><b>${E(t.table_name)}</b> · ${text}</span>`}).join('')}</section>`}
function commitmentContext(c){return{ambient:{enable:'Arthur can leave with a transition plan built from the actual care conversation.',bridge:'Capturing the conversation is not the same as creating the conditions for Arthur to understand and use it.',lead:'Where can Arthur have a clear, private and inclusive transition conversation?'},wayfinding:{enable:'Arthur can receive guidance that adapts as routes and destinations change.',bridge:'A technically correct route is not enough if Arthur cannot understand it, trust it or recover when guidance breaks down.',lead:'What combination of digital, physical and human guidance will help Arthur keep moving?'},meds:{enable:'Medication discrepancies can become visible before Arthur leaves.',bridge:'Detecting a discrepancy does not resolve it, explain it to Arthur or update every downstream source.',lead:'Who will own the resolution and make sure Arthur leaves with one clear medication plan?'},command:{enable:'The hospital can recognize constraints affecting Arthur’s transition and coordinate across departments.',bridge:'Seeing a blockage does not move Arthur. The capability only changes the experience when someone has authority to respond.',lead:'When the system sees a problem, who can actually do something about it?'}}[c.id]}
function commitmentRoom(){let slot=session.phase.endsWith('2')?'2':'1',cards=teams.map(t=>{let c=S().capabilities.find(x=>x.id===t.locked_capability),ctx=c?commitmentContext(c):null;return`<article><b>${E(t.table_name)}</b>${c?`<h2>${E(c.name)}</h2><p>${E(ctx.enable)}</p><blockquote>${E(ctx.bridge)}</blockquote><strong>${E(ctx.lead)}</strong>`:'<p>Waiting for the table to commit to a capability.</p>'}</article>`}).join('');return`<section class="commit-room"><div class="eyebrow">ACTIVATION ${slot} · NOW DESIGN AROUND IT</div><h1>THE CAPABILITY CHANGES WHAT IS POSSIBLE.<br>DESIGN DETERMINES WHAT ARTHUR EXPERIENCES.</h1><div class="commit-room-grid">${cards}</div></section>`}
function openingQuestionRoom(){return`<section class="instruction-room reflection-card"><div class="eyebrow">BEFORE WE EXPLAIN THE GAME</div><h1>WHAT IS THE BIGGEST CHALLENGE ARTHUR FACES GETTING HOME SAFELY?</h1><p>Answer on your phone. A few words is enough.</p></section>`}
function openingResponses(){return votes.filter(v=>v.stage_id===S().id&&v.decision==='opening_challenge'&&String(v.choice||'').trim())}
function openingCloudWords(){let counts={};openingResponses().forEach(v=>normalizeOpenWords(v.choice).forEach(w=>counts[w]=(counts[w]||0)+1));return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,30)}
function openingCloudRoom(){let words=openingCloudWords(),max=Math.max(1,...words.map(x=>x[1]));return`<section class="instruction-room reflection-card"><div class="eyebrow">WHAT THE ROOM SEES</div><h1>ARTHUR’S CHALLENGE, IN YOUR WORDS.</h1><div class="wordcloud">${words.length?words.map(([w,n])=>`<span class="w${Math.max(1,Math.min(4,Math.ceil(n/max*4)))}">${E(w)}</span>`).join(''):'<span class="w2">Waiting for responses…</span>'}</div><p>Keep this picture in mind. Now let’s design Arthur’s journey.</p></section>`}
function playerOpeningQuestion(){let mine=myVote('opening_challenge');playerPanel(`<div class="eyebrow">YOUR FIRST INSTINCT</div><h2>What is the biggest challenge Arthur faces getting home safely?</h2><p>A few words is enough.</p><textarea id="openingPlayerText" maxlength="160" placeholder="Type your thought...">${E(mine||'')}</textarea><button type="button" id="openingPlayerSubmit">${mine?'UPDATE MY THOUGHT':'SUBMIT MY THOUGHT'}</button>${mine?'<p><b>Submitted ✓</b> Follow the room screen.</p>':''}`);q('#openingPlayerSubmit').onclick=async()=>{let value=q('#openingPlayerText').value.trim();if(!value)return;await castVote('opening_challenge',value,q('#openingPlayerSubmit'))}}
function phaseCompleteForTable(t,phase){let active=tp(t).length;if(phase==='opening_question'){let n=votes.filter(v=>v.team_id===t.id&&v.stage_id===S().id&&v.decision==='opening_challenge'&&String(v.choice||'').trim()).length;return active>0&&n>=active}if(phase==='opening_cloud')return true;if(phase==='resource_check')return['proceed_current','add_support'].includes(t.status);if(phase==='cap_vote2'&&t.status==='proceed_current')return true;if(['cap_talk2','commit_vote2','commit_talk2'].includes(phase)&&t.status==='proceed_current')return true;if(phase.startsWith('cap_vote')){let slot=phase.endsWith('2')?'2':'1',d='capability'+slot,n=votes.filter(v=>v.team_id===t.id&&v.stage_id===S().id&&v.decision===d).length;return n>=active||t.status===`capability${slot}_closed`}if(phase.startsWith('cap_talk'))return!!t.locked_capability;if(phase.startsWith('commit_vote')){let slot=phase.endsWith('2')?'2':'1',d='commitment'+slot,n=votes.filter(v=>v.team_id===t.id&&v.stage_id===S().id&&v.decision===d).length;return n>=active||t.status===`commitment${slot}_closed`}if(phase.startsWith('commit_talk')){let slot=phase.endsWith('2')?2:1;return(t.investments||[]).some(i=>i.stage===S().id&&Number(i.slot)===slot)}return true}
function canAdvanceRoom(){return teams.length>0&&teams.every(t=>phaseCompleteForTable(t,session.phase))}
function journeyScreen(){return`<section class="journey-screen"><div class="eyebrow">ARTHUR’S CARE JOURNEY</div><h1>CARE DOESN’T STOP AT THE HOSPITAL DOOR.</h1><p class="journey-lead">Arthur moves through three connected environments. What the table activates in one environment can shape what becomes possible, necessary or difficult in the next.</p><div class="journey-map"><article class="active"><span>01 · HOSPITAL → HOME</span><h2>LEAVE WELL</h2><p>Can Arthur understand the plan, navigate the transition and arrive home with confidence?</p></article><article><span>02 · RECOVERY AT HOME</span><h2>RECOVER WELL</h2><p>Can Arthur recover safely, recognize change and get the right help when needed?</p></article><article><span>03 · BACK IN THE COMMUNITY</span><h2>LIVE WELL</h2><p>Can Arthur regain independence, reconnect and participate in everyday life?</p></article></div><div class="journey-line">ARTHUR MOVES FORWARD. THE DESIGN MOVES WITH ARTHUR.</div></section>`}
function commandCenterBrief(){return`<section class="capability-brief"><div class="eyebrow">YOUR TABLE IS CONSIDERING</div><h1>COMMAND CENTER OPERATIONS</h1><div class="brief-columns"><div><b>FOR ARTHUR</b><p>Arthur’s discharge depends on the unit, transport, pharmacy, available spaces and the route out of the hospital working together.</p><p>Command Center Operations can make constraints across that journey visible and coordinate a response.</p></div><div><b>FOR PEOPLE + OPERATIONS</b><p>The capability connects information that otherwise sits across separate departments and workflows.</p></div><div><b>FOR THE BUILT ENVIRONMENT</b><p>The capability provides visibility into movement, space, capacity, routes and alternatives.</p></div></div><div class="brief-warning"><b>VISIBILITY ALONE DOESN’T MOVE ARTHUR.</b><p>The hospital still needs authority to act, someone accountable for the response, available people and capacity, alternative routes or spaces, and a way to keep Arthur informed.</p></div></section>`}
function safeBack(){let i=phases.indexOf(session.phase);if(i<=0)return;if(i<phases.indexOf('cap_vote1'))return setPhase(phases[i-1]);sessionStorage.setItem('abd-preview-phase',phases[i-1]);location.reload()}
function facilitatorView(){let livePhase=session.phase,preview=sessionStorage.getItem('abd-preview-phase');if(preview)session={...session,phase:preview};let idx=phases.indexOf(session.phase),setup=session.phase==='elect',all=teams.length&&teams.every(ready);if(setup){layout(`<section class="join-simple"><div class="eyebrow">ARTHUR: BY DESIGN</div><h1>ROOM ${E(session.code)}</h1><div class="setup-qr">${qr(joinUrl())}</div><p>Scan → choose a table → add initials</p></section><section class="setup-tables"><div class="eyebrow">TABLES</div>${teams.map(t=>{let ps=tp(t),f=ps.find(p=>p.id===t.facilitator_player_id),state=t.status==='majority'?'MAJORITY RULE ✓':f?`${E(f.initials)} · READY ✓`:'CHOOSING FACILITATOR';return`<div><b>${E(t.table_name)}</b><span>${ps.length} joined · ${state}</span></div>`}).join('')||'<p>Waiting for players...</p>'}</section>${all?'<div class="all-ready">ALL TABLES READY</div>':''}<div class="controls"><button id="next" ${all?'':'disabled'}>MEET ARTHUR →</button></div>`);q('#next').onclick=()=>setPhase('journey');return}let main=session.phase==='journey'?journeyScreen():session.phase==='rules'?rules():session.phase==='story'?story():session.phase==='opening_question'?openingQuestionRoom():session.phase==='opening_cloud'?openingCloudRoom():session.phase==='needs'?needs():session.phase==='design_brief'?designBrief():session.phase==='example'?exampleScreen():session.phase.startsWith('commit_vote')?commitmentRoom():session.phase.startsWith('cap_vote')?`<section class="caproom"><div class="eyebrow">INVESTMENT ${session.phase.endsWith('2')?'2':'1'} OF 2</div><h1>WHICH CAPABILITY WILL HELP ARTHUR MOST?</h1><div class="roomcards">${capCards()}</div></section>`:`<section><div class="eyebrow">${session.phase.startsWith('cap_talk')?'TABLE CONVERSATION':'ROOM STORY'}</div><h1>${session.phase.startsWith('cap_talk')?'PRESSURE-TEST THE CHOICE':'LEAVE WELL'}</h1><p>${session.phase.startsWith('cap_talk')?'The vote is an initial instinct. The conversation creates the table commitment.':E(phaseLabels[session.phase]||'Arthur’s journey')}</p></section>`;layout(`<div class="late"><b>JOIN · ${E(session.code)}</b><div>${qr(joinUrl())}</div></div>${main}${tableStatus()}<div class="controls"><button id="back">BACK</button><button id="next" ${canAdvanceRoom()?'':'disabled'}>${session.phase==='complete'?'ROUND COMPLETE':canAdvanceRoom()?'CONTINUE':'WAITING FOR TABLES'}</button></div>`);if(preview){let controls=document.querySelector('.controls');if(controls)controls.innerHTML='<button id="returnLive">RETURN TO LIVE GAME</button>';q('#returnLive').onclick=()=>{sessionStorage.removeItem('abd-preview-phase');location.reload()};return}q('#back').onclick=()=>safeBack();q('#next').onclick=()=>session.phase!=='complete'&&canAdvanceRoom()&&setPhase(phases[idx+1])}
