function commitmentImplication(capId,choiceId,type){let map={command:{environment:{command0:'Unit teams need visibility into routes, capacity and alternatives.',command1:'The operating model needs real-time visibility into movement, spaces and capacity.',command2:'The liaison needs visibility across Arthur’s physical journey, not only the room.'},operations:{command0:'Escalation still needs a clearly defined path beyond the unit.',command1:'Authority, staffing and escalation rules must be explicit.',command2:'The liaison role, handoffs and availability must be staffed and sustained.'}},ambient:{environment:{ambient0:'The bedside must support privacy, participation and fewer interruptions.',ambient1:'Accessible consultation space must be available near the discharge path.',ambient2:'Protected transition capacity must remain available on the unit.'},operations:{ambient0:'The care team must control interruptions and verify understanding.',ambient1:'Someone must manage room availability and transition scheduling.',ambient2:'An owner must protect the space and the transition workflow.'}}};let fallback=type==='environment'?'The environment must support the selected care experience.':'Ownership, workflow and response must be explicit.';return map[capId]?.[type]?.[choiceId]||fallback}
