async function saveInvestment(commitmentId,slot){if(!team||!cap())return;let c=cap(),x=c.choices.find(a=>a.id===commitmentId),[ca,ch]=costs[c.id],items=[...(team.investments||[])],key=`${S().id}:${slot}`,existing=items.findIndex(i=>i.key===key);let item={key,slot:Number(slot),stage:S().id,capabilityId:c.id,name:c.name,capital:ca,change:ch,commitmentId,choice:x,architecture:architectureChoice(c.id,commitmentId)};if(existing>=0)items[existing]=item;else if(items.filter(i=>i.stage===S().id).length<2)items.push(item);else return alert('This setting already has two activations.');let capital=7-items.filter(i=>i.stage===S().id).reduce((n,i)=>n+(i.capital||0),0),change=6-items.filter(i=>i.stage===S().id).reduce((n,i)=>n+(i.change||0),0);let buttons=[...document.querySelectorAll('#commitDesign,[data-altcommit],[data-commit]')];buttons.forEach(b=>b.disabled=true);let r=await supabase.from('teams').update({investments:items,capital,change_budget:change,locked_commitment:commitmentId,status:'design locked'}).eq('id',team.id).select('*').single();if(r.error){buttons.forEach(b=>b.disabled=false);return alert(r.error.message)}team=r.data;teams=teams.map(t=>t.id===team.id?team:t);render()}
