async function setTablePath(status){let r=await supabase.from('teams').update({status}).eq('id',team.id).select('*').single();if(r.error)return showInlineError(r.error.message);team=r.data;teams=teams.map(t=>t.id===team.id?team:t);render()}
function passive(title,body){playerPanel(`<div class="eyebrow">${E(title)}</div><h2>${E(body)}</h2><p>Follow the room screen.</p>`)}
function playerView(){if(!me||!team)return joinForm(qs.get('room')||'');let p=session.phase;if(['cap_vote2','cap_talk2','commit_vote2','commit_talk2'].includes(p)&&team.status==='proceed_current')return playerPanel(`${bars()}<div class="eyebrow">DESIGN COMPLETE</div><h2>Your table is proceeding with the current design.</h2><p>Follow the room while other tables consider a supporting capability.</p>`);if(p.startsWith('commit_talk')&&!phaseCompleteForTable(team,p)&&!myVote('commitment'+(p.endsWith('2')?'2':'1')))return commitmentVote();if(['resource_check','cap_vote2','designed','event','predict','consequence','principle','complete'].includes(p)&&!investments().length)return team.locked_capability?commitmentVote():capVote();if(p==='elect')return election();if(p==='design_brief')return playerPanel(`<div class="eyebrow">DESIGNING FOR ARTHUR</div><h2>Each capability changes more than technology.</h2><p>Consider the impact on Arthur’s journey, people and operations, and the built environment.</p>`);if(p==='rules')return playerPanel(`<div class="eyebrow">THE ACTIVATION CHALLENGE</div><h2>Design for what comes next. Activate what matters now.</h2><div class="phone-rules"><div><b>7 Capital</b><span>Implementation capacity</span></div><div><b>6 Change</b><span>Organizational capacity</span></div><div><b>Up to 2 activations</b><span>Each must fit both forms of capacity</span></div></div><p>Explore → Vote → Discuss → Commit → Design around it.</p>`);if(p==='journey')return playerPanel(`<div class="eyebrow">ARTHUR’S CARE JOURNEY</div><h2>Leave Well → Recover Well → Live Well</h2><p>Arthur will move from hospital to home, through recovery and back into community life. What the table activates now can shape what follows.</p>`);if(p==='story')return passive('MEET ARTHUR','Arthur is going home today.');if(p==='opening_question')return playerOpeningQuestion();if(p==='opening_cloud')return playerPanel(`<div class="eyebrow">WHAT THE ROOM SEES</div><h2>Your table’s responses are becoming the room word cloud.</h2><p>Follow the room screen.</p>`);if(p==='needs')return playerPanel(`<div class="eyebrow">WHAT ARTHUR NEEDS</div><h2>Leaving well means Arthur needs to:</h2><div class="phone-needs"><div><i class="need-box-icon">?</i><b>UNDERSTAND</b><span>Does Arthur know what happened, what changed and what comes next?</span></div><div><i class="need-box-icon">→</i><b>MOVE</b><span>Can Arthur move safely and confidently from hospital to home?</span></div><div><i class="need-box-icon">∞</i><b>CONNECT</b><span>to medications, people and follow-up that support recovery.</span></div><div><i class="need-box-icon">✓</i><b>TRUST</b><span>that Arthur knows what to do and who will respond as conditions change.</span></div></div><p><b>Your table will design around all four.</b></p>`);if(p==='example')return playerPanel(`<div class="eyebrow">HOW TO READ A CAPABILITY</div><h2>Ambient Discharge + Handoff</h2><p>Tap a capability title during voting to open the long view: Arthur outcome, built-environment implication, operating commitment and cost.</p>`);if(p==='cap_vote1'||p==='cap_vote2')return capVote();if(p==='cap_talk1'||p==='cap_talk2')return capTalk();if(p==='commit_vote1'||p==='commit_vote2')return commitmentVote();if(p==='commit_talk1'||p==='commit_talk2')return commitmentTalk();if(p==='resource_check')return resourceCheck();return passive(p.replaceAll('_',' '),'Follow Arthur’s journey on the room screen.')}
function render(){mode==='facilitator'?facilitatorView():playerView()}

const soloFuture={ambient:'Arthur leaves knowing what happened and what comes next.',wayfinding:'Arthur can find the way out even when the route changes.',meds:'Arthur leaves with one medication story, not several conflicting ones.',command:'Arthur’s transition can be coordinated when hospital systems collide.'};
const soloWatch={ambient:'Privacy, family participation and who verifies understanding.',wayfinding:'Physical reinforcement, accessibility and human fallback.',meds:'Who resolves the discrepancy and explains one clear plan.',command:'Authority, response capacity and who keeps Arthur informed.'};
function soloCommitmentView(capId,x){let env={ambient:{bedside:'Arthur stays where Arthur is, but privacy and interruptions remain constrained.',shared:'A focused consultation space supports family participation, but depends on room availability and another move.',dedicated:'Protected transition space supports privacy and reliability, but consumes space and operating stewardship.'},wayfinding:{digital:'Digital guidance changes quickly, but Arthur may have no reinforcement when the route looks unfamiliar.',layered:'Digital, physical and human cues give Arthur multiple ways to recover when conditions change.',escort:'A human guide can interpret conditions in the moment, but the model depends on staffing and handoff reliability.'},meds:{nurse:'The closest clinical team owns resolution, but discharge work and competing demands can delay action.',pharmacy:'Specialist review improves accuracy, but adds another handoff and timing dependency.',huddle:'A transition huddle connects medication, workflow and departure decisions, but requires protected time.'},command:{unit:'Local teams know Arthur’s context, but may lack authority over cross-hospital constraints.',center:'Cross-hospital authority can coordinate action, but only if staffing and escalation rules are real.',liaison:'One accountable guide can hold Arthur’s journey together, but the role must be staffed and sustained.'}};return env[capId]?.[x.id]||x.compromise}
function soloPortfolioSignal(){return`<section class="portfolio-signal"><h3>YOUR ACTIVATION STRATEGY</h3><p><b>Focused capabilities</b> preserve capacity to strengthen a second part of Arthur’s transition.</p><p><b>Large operating capabilities</b> may coordinate more of the journey, but can consume nearly all implementation and organizational capacity.</p></section>`}
const soloVisuals={meet:asset('arthur-leaving-well.png'),journey:asset('arthur-connected-care.png'),needs:asset('arthur-leave-well.png'),rules:asset('arthur-leave-well.png'),capability:asset('arthur-connected-care.png'),'activation-impact':asset('arthur-leaving-well.png'),commitment:asset('arthur-leaving-well.png'),'commitment-impact':asset('arthur-leaving-well.png'),operations:asset('arthur-connected-care.png'),'operations-impact':asset('arthur-connected-care.png'),design:asset('arthur-connected-care.png'),event:asset('arthur-connected-care.png'),pressure:asset('arthur-connected-care.png'),consequence:asset('arthur-connected-care.png'),principle:asset('arthur-community.png')};
function visualTitle(phase){return{meet:'Arthur is going home.',journey:'A journey of care. A lifetime of possibility.',needs:'What does leaving well require for Arthur?',rules:'Design for what comes next.',capability:'What will you activate for Arthur?','activation-impact':'Technology changed what is possible.',commitment:'Now design around it.','commitment-impact':'The decision changed Arthur’s experience.',operations:'Make it operational.','operations-impact':'Adaptability needs ownership.',design:'Your complete design.',event:'Conditions change.',pressure:'Arthur reaches the junction.',consequence:'Arthur experiences the design.',principle:'Future readiness by design.'}[phase]||'Arthur: By Design'}
function visualBand(phase){let src=soloVisuals[phase]||soloVisuals.meet;return`<section class="visual-band"><img src="${src}" alt="Arthur’s care journey"><div class="visual-band-copy"><span>ARTHUR: BY DESIGN</span><strong>${E(visualTitle(phase))}</strong></div></section>`}
const SOLO_KEY='arthur-by-design-solo-v1';
function defaultSolo(){return{phase:'meet',capital:7,change:6,activations:[],pendingCapability:null,pendingCommitment:null,prediction:null,response:null,reviseIndex:null,comparison:null,strategy:null,history:[],pendingOperation:null,eventId:null,eventSeed:null,responseCost:null,responseTransaction:null,openingResponse:null}}
let soloState=null;
function loadSolo(){try{soloState=JSON.parse(localStorage.getItem(SOLO_KEY))||defaultSolo()}catch{soloState=defaultSolo()}}
function saveSolo(){localStorage.setItem(SOLO_KEY,JSON.stringify(soloState))}
function soloSet(phase){if(soloState.phase!==phase){soloState.history=soloState.history||[];soloState.history.push(soloState.phase)}soloState.phase=phase;saveSolo();soloRender()}
const lockedBackPhases=new Set(['activation-impact','commitment-impact','design','event','pressure','consequence','choose-revision','revise','principle']);
function soloBack(){if(lockedBackPhases.has(soloState.phase))return;let h=soloState.history||[];if(!h.length)return;soloState.phase=h.pop();soloState.history=h;saveSolo();soloRender()}

function soloNav(){let disabled=lockedBackPhases.has(soloState.phase)||!(soloState.history||[]).length?'disabled':'';let label=lockedBackPhases.has(soloState.phase)?'DECISION COMMITTED':'← BACK';return`<div class="solo-nav"><button type="button" id="soloBack" ${disabled}>${label}</button><span>ARTHUR: BY DESIGN</span></div>`}

function soloGo(phase){soloSet(phase)}
function soloReset(){localStorage.removeItem(SOLO_KEY);soloState=defaultSolo();saveSolo();soloRender()}
function soloShell(body,{decision=false,conversation=false,complete=false,visual=true}={}){let phase=soloState?.phase||'meet',instruction=['rules','card-guide','capability-intro'].includes(phase);let cls=decision?'solo-decision':conversation?'solo-conversation':complete?'solo-complete':instruction?'instruction-screen':'';layout(`${soloNav()}<div class="solo-utility"><b>SINGLE PLAYER</b><button type="button" id="soloRestart">START OVER</button></div>${visual?visualBand(phase):''}<main class="solo-game ${cls}">${body}</main>`);q('#soloRestart').onclick=()=>{if(confirm('Start Arthur’s journey again?'))soloReset()};if(q('#soloBack'))q('#soloBack').onclick=()=>soloBack()}
function soloButton(id,label,fn,secondary=false){setTimeout(()=>{let b=q('#'+id);if(b)b.onclick=fn},0);return`<button type="button" id="${id}" class="${secondary?'secondary':''}">${label}</button>`}
function soloCapability(id){return S().capabilities.find(c=>c.id===id)}
function soloCost(id){return costs[id]||[0,0]}
function soloMeet(){soloShell(`<section class="arthur-hero branded-intro"><img src="${asset('arthur-intro.png')}" alt="Arthur preparing to leave the hospital"><div class="brandline"><span>ARTHUR: BY DESIGN</span><strong>STANTEC</strong></div><div class="arthur-hero-copy"><div class="eyebrow">MEET ARTHUR</div><h1>ARTHUR IS<br>GOING HOME.</h1><p class="solo-lead intro-short">Cardiac surgery is behind Arthur.<br><b>The harder part may be what comes next.</b></p>${soloButton('soloNext','FOLLOW ARTHUR →',()=>soloGo('opening-question'))}</div></section>`,{visual:false})}
function normalizeOpenWords(text){return String(text||'').toLowerCase().replace(/[^a-z0-9\s-]/g,' ').split(/\s+/).filter(w=>w&& !['the','a','an','and','or','to','of','for','his','her','their','getting','home','arthur'].includes(w))}
function soloOpeningQuestion(){soloShell(`<section class="reflection-card"><div class="eyebrow">BEFORE WE SHOW YOU THE GAME</div><h1>WHAT IS THE BIGGEST CHALLENGE ARTHUR FACES GETTING HOME SAFELY?</h1><p>A few words is enough.</p><textarea id="openingText" maxlength="160" placeholder="Type your thought...">${E(soloState.openingResponse||'')}</textarea><button type="button" id="submitOpening">SUBMIT MY THOUGHT</button></section>`,{visual:false});q('#submitOpening').onclick=async()=>{let value=q('#openingText').value.trim();if(!value)return;soloState.openingResponse=value;saveSolo();await savePlayerResponse('leave_well_opening_challenge',value);soloGo('opening-cloud')}}
function soloOpeningCloud(){let words=normalizeOpenWords(soloState.openingResponse),unique=[...new Set(words)].slice(0,12);soloShell(`<section class="reflection-card"><div class="eyebrow">YOUR FIRST INSTINCT</div><h1>YOU SAID</h1><div class="reflection-return">“${E(soloState.openingResponse)}”</div><div class="wordcloud">${unique.map((w,i)=>`<span class="w${Math.min(4,1+(i%4))}">${E(w)}</span>`).join('')}</div><p>Keep that thought in mind. Now let’s design Arthur’s journey.</p>${soloButton('openContinue','CONTINUE TO THE JOURNEY →',()=>soloGo('journey'))}</section>`,{visual:false})}
function soloJourney(){soloShell(`<section class="journey-editorial"><div class="journey-brand"><span>ARTHUR: BY DESIGN</span><strong>STANTEC</strong></div><h1>A JOURNEY OF CARE.<br>A LIFETIME OF POSSIBILITY.</h1><p class="journey-intro">Arthur moves through three connected environments. What you design today can shape what’s possible tomorrow.</p><div class="journey-visual-grid journey-select-grid"><button type="button" class="journey-path" data-path="leave"><img src="${asset('arthur-leave-well.png')}" alt="Hospital to home"><span class="journey-icon">↗</span><span class="journey-path-copy"><b>LEAVE WELL</b><strong>Hospital → Home</strong><small>Can Arthur understand the plan, navigate the transition and arrive home with confidence?</small></span></button><button type="button" class="journey-path" data-path="recover"><img src="${asset('arthur-recover-well.png')}" alt="Recovery at home"><span class="journey-icon">⌂</span><span class="journey-path-copy"><b>RECOVER WELL</b><strong>At Home</strong><small>Can Arthur recover safely, recognize change and get the right help when needed?</small></span></button><button type="button" class="journey-path" data-path="live"><img src="${asset('arthur-live-well.png')}" alt="Return to community life"><span class="journey-icon">◎</span><span class="journey-path-copy"><b>LIVE WELL</b><strong>In the Community</strong><small>Can Arthur regain independence, reconnect and participate in everyday life?</small></span></button></div><div class="journey-focus" id="journeyFocus"><b>TODAY WE BEGIN HERE: LEAVE WELL</b></div></section>`,{visual:false});let paths=document.querySelectorAll('.journey-path');paths.forEach(btn=>btn.onclick=()=>{paths.forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');let path=btn.dataset.path;if(path==='leave'){soloGo('needs');return}let label=path==='recover'?'RECOVER WELL':'LIVE WELL',f=q('#journeyFocus');if(f)f.innerHTML=`<b>${label}</b><span>COMING NEXT · LEAVE WELL IS ACTIVE</span>`})}
function arthurKey(active=[]){let items=[['UNDERSTAND','?'],['MOVE','→'],['CONNECT','∞'],['TRUST','✓']];return `<div class="arthur-key"><strong>WHAT MATTERS TO ARTHUR</strong>${items.map(([n,g])=>`<span class="${active.length&&!active.includes(n)?'muted':''}"><i>${g}</i>${n}</span>`).join('')}</div>`}
const playerCapabilityNames={ambient:'SMART DISCHARGE',wayfinding:'SMART ROUTES',meds:'MEDICATION CHECK',command:'COORDINATED RESPONSE'};
const playerCapabilityLines={ambient:'AI turns the discharge conversation into a plan Arthur can take home.',wayfinding:'Directions adjust when Arthur’s path through the hospital changes.',meds:'AI checks medications and changes before Arthur leaves.',command:'People and information coordinate when Arthur’s transition changes.'};
const playerCapabilityWhat={ambient:'Creates one take-home plan.',wayfinding:'Updates Arthur’s route.',meds:'Finds medication conflicts before departure.',command:'Makes transition issues visible across the team.'};
const playerCapabilityWhy={ambient:'Arthur knows what changed and what comes next.',wayfinding:'Arthur can keep moving when the expected path changes.',meds:'Arthur leaves with one medication story.',command:'Arthur gets a coordinated response instead of fragmented answers.'};
const playerCapabilityDesign={ambient:'Give Arthur privacy and a place to review the plan before leaving.',wayfinding:'Digital directions need physical cues at real decision points.',meds:'Create a clear place to review, confirm and correct medications.',command:'Put coordination where teams can see and act on transition problems.'};
const playerCapabilityOperate={ambient:'Someone must confirm and own the plan.',wayfinding:'Someone must keep digital and physical guidance synchronized.',meds:'Someone must own medication changes across the handoff.',command:'Someone must have authority and capacity to respond.'};
function playerName(id){return playerCapabilityNames[id]||soloCapability(id)?.name||id}
function capabilityNeedTags(id){return `<div class="need-card-tags">${(needMap[id]||[]).map(n=>`<span>${n==='UNDERSTAND'?'?':n==='MOVE'?'→':n==='CONNECT'?'∞':'✓'} ${n}</span>`).join('')}</div>`}

function learnMoreDetails(id){return `<details class="learn-more"><summary>LEARN MORE</summary><div class="learn-more-grid"><section><b>FOR ARTHUR</b><p>${E(playerCapabilityWhy[id])}</p></section><section><b>DESIGN CONSIDERATION</b><p>${E(playerCapabilityDesign[id])}</p></section><section><b>TO MAKE IT WORK</b><p>${E(playerCapabilityOperate[id])}</p></section></div></details>`}

function soloNeeds(){soloShell(`<div class="eyebrow">LEAVE WELL · THE CHALLENGE</div><h1>FOUR THINGS MATTER.</h1>${arthurKey()}<div class="solo-needs"><div><b>UNDERSTAND</b><span>Does Arthur know what happened, what changed and what comes next?</span></div><div><b>MOVE</b><span>Can Arthur move safely and confidently from hospital to home?</span></div><div><b>CONNECT</b><span>Can Arthur stay connected to medications, people and follow-up?</span></div><div><b>TRUST</b><span>Does Arthur trust what to do next and who will respond?</span></div></div><div class="challenge-brief compact-brief"><b>YOUR CHALLENGE</b><span>Design an environment that helps Arthur leave well.</span></div>${soloButton('soloNext','SHOW ME HOW →',()=>soloGo('rules'))}`)}
function soloRules(){soloShell(`<span class="instruction-pill">HOW TO PLAY</span><div class="eyebrow">INSTRUCTION · HOW THE GAME WORKS</div><h1>HOW WILL WE DESIGN ARTHUR’S PATH?</h1><div class="game-loop compact-loop"><article><span>◉</span><b>CHOOSE</b><small>Invest in AI-powered options.</small></article><article><span>◇</span><b>DESIGN</b><small>Make it work here.</small></article><article><span>↗</span><b>ADAPT</b><small>Strengthen or extend.</small></article><article><span>⚡</span><b>RESPOND</b><small>Conditions change.</small></article></div>${arthurKey()}<div class="resource-row"><strong>YOUR RESOURCES</strong><span class="resource-chip"><i>◆</i> 7 CAPITAL</span><span class="resource-chip"><i>●</i> 6 CHANGE</span><span class="resource-note">Capital funds what you build. Change is the capacity to implement it. Invest in up to 2 AI-powered options.</span></div>${soloButton('soloNext','LEARN HOW TO READ A CARD →',()=>soloGo('card-guide'))}`)}
function capabilityPreviewCards(){return S().capabilities.map(c=>{let [ca,ch]=soloCost(c.id);return `<article class="visual-cap-preview"><img src="${asset(leaveWellVisuals[c.id])}" alt="${E(playerName(c.id))}"><div class="visual-cap-copy"><div class="resource-mini"><span><i>◆</i> ${ca}</span><span><i>●</i> ${ch}</span></div><h2>${E(playerName(c.id))}</h2><small class="technical-name">${E(c.name)}</small><p>${E(playerCapabilityLines[c.id])}</p>${capabilityNeedTags(c.id)}</div></article>`}).join('')}

function soloCapabilityIntro(){soloShell(`<span class="instruction-pill">HOW TO PLAY</span><div class="eyebrow">ONE LAST THING</div><h1>READ FOR ARTHUR FIRST. USE COST TO FORCE THE TRADE-OFF.</h1>${arthurKey()}<div class="instruction-note"><b>ON EACH CARD</b><br>Start with what Arthur gains and the design challenge. Open More Detail only when you want the technology, built-environment, and operating implications.</div>${soloButton('soloNext','START THE INVESTMENT ROUND →',()=>soloGo('capability'))}`)}

function soloCardGuide(){let c=soloCapability('ambient'),[ca,ch]=soloCost(c.id);soloShell(`<span class="instruction-pill">HOW TO PLAY</span><div class="eyebrow">INSTRUCTION · SAMPLE CARD</div><h1>HOW TO READ AN INVESTMENT CARD.</h1><p class="investment-teach"><b>Technology creates the capability.</b> Design determines Arthur’s experience.</p>${arthurKey(needMap[c.id])}<article class="learning-card visual-learning"><div class="learning-media"><img src="${asset(leaveWellVisuals[c.id])}" alt="Smart discharge"><div>${capabilityNeedTags(c.id)}</div></div><div class="learning-content"><div class="learning-title"><div><span class="sample-ribbon">SAMPLE CARD</span><h2>${playerName(c.id)}</h2><small>${E(playerCapabilityLines[c.id])}</small></div><div class="resource-mini"><span><i>◆</i> ${ca}</span><span><i>●</i> ${ch}</span></div></div><div class="learning-points"><section><b>WHAT IT DOES</b><p>${E(playerCapabilityWhat[c.id])}</p></section><section><b>WHY ARTHUR CARES</b><p>${E(playerCapabilityWhy[c.id])}</p></section><section><b>TO MAKE IT WORK</b><p>${E(playerCapabilityOperate[c.id])}</p></section></div><div class="design-focus"><b>DESIGN CONSIDERATION</b><p>${E(playerCapabilityDesign[c.id])}</p></div></div></article>${soloButton('soloNext','GOT IT. SHOW ME THE OPTIONS →',()=>soloGo('capability-intro'))}`,{visual:false})}

function soloBars(){return`<div class="bars"><div><b>CAPITAL</b><span>${'●'.repeat(soloState.capital)}${'○'.repeat(7-soloState.capital)}</span><strong>${soloState.capital}</strong></div><div><b>CHANGE</b><span>${'●'.repeat(soloState.change)}${'○'.repeat(6-soloState.change)}</span><strong>${soloState.change}</strong></div></div>`}
const spatialDesignChallenges={
 ambient:'Where can Arthur privately review the plan, ask questions and confirm understanding before leaving?',
 wayfinding:'How can architecture, visible landmarks, dynamic information and human assistance reinforce a changing route?',
 meds:'Where can Arthur, caregivers and clinicians resolve discrepancies together while maintaining privacy?',
 command:'Where can teams recognize disruption, coordinate a response and safely accommodate Arthur while the plan changes?'
};
function vitruviusLensHTML(){return `<section class="vitruvius-lens"><strong>THREE QUESTIONS · ONE ENVIRONMENT</strong><div class="vitruvius-grid"><article><span>UTILITAS</span><b>USEFUL</b><p>Can Arthur do what Arthur needs?</p></article><article><span>FIRMITAS</span><b>RESILIENT</b><p>Will the design still work when plans change?</p></article><article><span>VENUSTAS</span><b>HUMAN</b><p>Does Arthur retain dignity, confidence and independence?</p></article></div></section>`}
function responseEnvironmentCopy(id){return {use:'Relies on the assistance points, routes and spaces already created.',adapt:'Reconfigures available transition space and staffing to accommodate the disruption.',escalate:'Activates additional supported space and response capacity if resources allow.'}[id]||''}
function architectureAssessment(r){let useful=r.outcome==='ABSORBED'?['held','HELD','Arthur could complete the next step using the design.']:r.outcome==='STRAINED'?['strained','PARTIAL','Arthur completed the transition, but the next step still depended on support outside the environment.']:['exposed','EXPOSED','Arthur could not reliably complete the next step with the available design.'];let resilient=r.outcome==='ABSORBED'?['held','HELD','The environment and operating model absorbed the changed conditions.']:r.outcome==='STRAINED'?['strained','STRAINED','The design responded, but remained dependent on people, capacity or fallback resources.']:['exposed','FAILED','The changed conditions exceeded the design and available response.'];let human=(r.scores?.TRUST||0)>=2?['held','SUPPORTED','Arthur retained meaningful confidence, agency and human support.']:['strained','PARTIAL','The disruption reduced Arthur’s confidence or independence even when the transition continued.'];return {useful,resilient,human}}
function architectureAssessmentHTML(r){let a=architectureAssessment(r),card=(latin,title,x)=>`<article class="${x[0]}"><span>${latin}</span><h3>${title}</h3><em>${x[1]}</em><p>${E(x[2])}</p></article>`;return `<section class="architecture-performance"><h2>HOW DID YOUR DESIGN HOLD UP?</h2><div class="architecture-performance-grid">${card('UTILITAS','USEFUL',a.useful)}${card('FIRMITAS','RESILIENT',a.resilient)}${card('VENUSTAS','HUMAN',a.human)}</div></section>`}
function architecturalObligationsHTML(r){let a=architectureAssessment(r);return `<section><div class="eyebrow">YOUR ARCHITECTURAL OBLIGATIONS</div><div class="architectural-obligations"><article><span>USEFUL</span><b>Make Arthur’s changed next step obvious and reachable.</b></article><article><span>RESILIENT</span><b>Create a usable fallback when the preferred handoff fails.</b></article><article><span>HUMAN</span><b>Give Arthur a protected place to understand and regain confidence.</b></article></div></section>`}
function soloCapabilities(){let used=soloState.activations.map(a=>a.capabilityId),defs={ambient:'AI captures the discharge conversation and turns it into a clear transition plan that can follow Arthur from hospital to home.',wayfinding:'Digital guidance updates Arthur’s route as hospital destinations, access or conditions change.',meds:'AI compares medication information across the care journey to expose discrepancies before Arthur leaves.',command:'A connected operating capability makes constraints across Arthur’s transition visible and helps coordinate responses across departments.'},cards=S().capabilities.filter(c=>!used.includes(c.id)).map(c=>{let[ca,ch]=soloCost(c.id),disabled=ca>soloState.capital||ch>soloState.change;return`<article class="medium-cap-card ${disabled?'disabled':''}"><img src="${asset(leaveWellVisuals[c.id])}" alt="${E(playerName(c.id))}"><div class="medium-cap-body"><div class="medium-cap-head"><div><div class="eyebrow">AI-POWERED OPTION</div><h2>${E(playerName(c.id))}</h2><small>${E(c.name)}</small></div><strong class="medium-cap-cost">◆ ${ca} · ● ${ch}</strong></div><p>${E(playerCapabilityLines[c.id])}</p><div class="medium-cap-gain"><b>ARTHUR GAINS</b><br>${E(soloFuture[c.id])}</div><div class="medium-cap-challenge"><b>DESIGN CHALLENGE</b><br>${E(spatialDesignChallenges[c.id]||soloWatch[c.id])}</div>${capabilityNeedTags(c.id)}<details><summary>MORE DETAIL</summary><div class="medium-cap-detail"><p><b>TECHNOLOGY CAN</b><br>${E(playerCapabilityLines[c.id])}</p><p><b>BUILT ENVIRONMENT</b><br>${E(capabilityLong(c)?.environment||playerCapabilityDesign[c.id])}</p><p><b>PEOPLE + OPERATIONS</b><br>${E(capabilityLong(c)?.operations||playerCapabilityOperate[c.id])}</p><p><b>WHY ARTHUR CARES</b><br>${E(playerCapabilityWhy[c.id])}</p></div></details><button type="button" data-solo-cap="${c.id}" ${disabled?'disabled':''}>${disabled?'NOT ENOUGH CAPACITY':'INVEST IN THIS OPTION'}</button></div></article>`}).join('');soloShell(`${soloBars()}<div class="eyebrow">ARTHUR IS READY TO LEAVE THIS AFTERNOON</div><h1>WHAT WILL YOU INVEST FIRST?</h1><p class="solo-lead">Choose the option that creates the strongest next step for Arthur. Cost forces the trade-off.</p><div class="solo-choice-list">${cards}</div>`,{decision:true});document.querySelectorAll('[data-solo-cap]').forEach(b=>b.onclick=()=>{soloState.pendingCapability=b.dataset.soloCap;saveSolo();soloSet('activation-impact')})}

const soloOperations={ambient:[{id:'protect',label:'Protect scheduled transition capacity',benefit:'Arthur gets a reliable time and setting for the discharge conversation.',tradeoff:'Protected capacity cannot be used freely for other demands.',dependency:'Scheduling ownership and protected time must hold when the hospital gets busy.',effect:-1,aha:'A designed place becomes dependable only when operating capacity is protected.'},{id:'flex',label:'Keep the setting flexible and shared',benefit:'The hospital preserves flexibility for other uses.',tradeoff:'Arthur’s conversation can be displaced when demand rises.',dependency:'The team needs a fallback when the preferred setting is unavailable.',effect:1,aha:'Flexible space is not the same as reliable care capacity.'},{id:'priority',label:'Prioritize discharge when demand rises',benefit:'Arthur’s transition receives explicit priority at critical times.',tradeoff:'Other work may wait or be rerouted.',dependency:'Priority rules and escalation ownership must be explicit.',effect:0,aha:'Priority is an operating choice, not a feature of the room.'}],wayfinding:[{id:'unit',label:'Give the unit ownership of route updates',benefit:'The team closest to Arthur can react quickly to local changes.',tradeoff:'The unit may not see system-wide route changes soon enough.',dependency:'Local staff need current route information and authority to update cues.',effect:0,aha:'Layered guidance is resilient only when someone owns synchronization.'},{id:'facilities',label:'Give Facilities / Wayfinding ownership',benefit:'Physical cues and route standards can be managed consistently.',tradeoff:'Updates may not match the speed of a clinical transition.',dependency:'A rapid update workflow must connect operational change to physical cues.',effect:-1,aha:'Physical adaptability has a response time.'},{id:'command',label:'Coordinate updates through the command center',benefit:'Route, capacity and cross-department changes can be coordinated from one view.',tradeoff:'The model depends on command authority and available responders.',dependency:'Digital, physical and human channels must receive the same change.',effect:-1,aha:'Coordination adds value only when it can change the environment in time.'}],meds:[{id:'nurse',label:'Protect nurse resolution time',benefit:'The clinician closest to Arthur can resolve and explain discrepancies.',tradeoff:'Protected time competes with discharge and unit demands.',dependency:'Coverage must absorb other tasks while medication issues are resolved.',effect:0,aha:'Ownership without protected capacity is fragile.'},{id:'pharmacy',label:'Guarantee pharmacy response coverage',benefit:'Specialist review remains available during transition.',tradeoff:'Arthur’s flow depends on a cross-department service level.',dependency:'Response times and escalation must be explicit.',effect:0,aha:'A specialist workflow becomes part of discharge design.'},{id:'huddle',label:'Protect a transition huddle',benefit:'Medication, discharge and movement decisions are reconciled together.',tradeoff:'Several people must be available at the same time.',dependency:'The hospital must protect shared transition time.',effect:-1,aha:'Integration requires operating capacity, not just connected data.'}],command:[{id:'existing',label:'Coordinate existing resources',benefit:'The hospital uses visibility to redirect what is already available.',tradeoff:'There may be nothing available to redirect at the critical moment.',dependency:'Authority helps only when people, routes or space can actually move.',effect:1,aha:'Visibility does not create capacity.'},{id:'protect',label:'Protect transition capacity',benefit:'People, routes or spaces remain available for transitions like Arthur’s.',tradeoff:'Protected capacity reduces flexibility for other demands.',dependency:'The hospital must decide what capacity is worth defending.',effect:-1,aha:'Resilience often comes from capacity designed before disruption.'},{id:'flex',label:'Maintain flexible response capacity',benefit:'The system can redeploy support as disruptions emerge.',tradeoff:'Flex capacity carries ongoing staffing and operating cost.',dependency:'Roles, authority and triggers for redeployment must be clear.',effect:-1,aha:'Flexibility is an operating capability that must be funded and designed.'}]};
function capabilityAha(id){return{ambient:'Technology can create the transition plan. Design creates the conditions for Arthur to understand and use it.',wayfinding:'Route intelligence can change instantly. The physical environment and human fallback must be able to change with it.',meds:'Finding the discrepancy is a technology function. Resolving, explaining and owning it is an operating design decision.',command:'Visibility does not create capacity. Seeing the problem matters only when the hospital is designed to respond.'}[id]}
function soloActivationImpact(){let c=soloCapability(soloState.pendingCapability),[ca,ch]=soloCost(c.id);if(c.id==='command'){soloShell(coordinatedResponseTransitionHTML({asset}),{complete:true,visual:false});runCoordinatedResponseTransition(document,{onNext:()=>soloSet('commitment')});return}if(c.id==='ambient'){soloShell(smartDischargeTransitionHTML({asset}),{complete:true,visual:false});runSmartDischargeTransition(document,{onNext:()=>soloSet('commitment')});return}if(c.id==='meds'){soloShell(medicationInvestmentTransition({asset,escape:E}),{complete:true,visual:false});runMedicationInvestmentTransition(document,{onNext:()=>soloSet('commitment')});return}soloShell(`<div class="eyebrow">DECISION → IMPACT → AHA</div><h1>YOU INVESTED IN ${E(c.name.toUpperCase())}.</h1>${storyboardHTML({...soloState,activations:[...soloState.activations,{capabilityId:c.id}]},'capability',asset)}<section class="impact-hero"><b>HERE’S WHAT THAT CHANGES FOR ARTHUR</b><h2>${E(soloFuture[c.id])}</h2></section><div class="impact-grid"><div><b>FOR ARTHUR</b><p>${E(capabilityLong(c)?.arthur||c.purpose)}</p></div><div><b>PEOPLE + OPERATIONS</b><p>${E(capabilityLong(c)?.operations||'Ownership and workflow must now be established.')}</p></div><div><b>BUILT ENVIRONMENT</b><p>${E(capabilityLong(c)?.environment||'The environment must support the experience.')}</p></div><div><b>CAPACITY</b><p>${ca} Capital · ${ch} Change will be committed once you finish designing how this works.</p></div></div><blockquote class="micro-aha"><b>AHA</b><p>${E(capabilityAha(c.id))}</p></blockquote>${soloButton('soloNext','NOW DESIGN AROUND IT',()=>soloSet('commitment'))}`,{complete:true})}
function soloCommitmentOptions(id){let c=soloCapability(id);let opts=c?.choices||c?.designChoices||c?.commitments||c?.options;return Array.isArray(opts)?opts:[]}
