function plainDesignChoice(capabilityId,x,index){return standardizedDesignChoices[capabilityId]?.[index]||{title:x.label,line:x.benefit,consideration:x.compromise,image:leaveWellVisuals[capabilityId]}}

function soloSaveActivation(capabilityId,choice,index){
 const c=soloCapability(capabilityId);if(!c||!choice)throw new Error('Design option is missing.');
 const [ca,ch]=soloCost(c.id);if(ca>soloState.capital||ch>soloState.change)throw new Error('Not enough Capital or Change remains.');
 const architecture=architectureChoice(c.id,choice.id);
   const activation={capabilityId:c.id,commitmentId:choice.id,designIndex:index,capital:ca,change:ch,choice,architecture,operation:{id:'embedded',label:'Embedded operating commitment',description:choice.compromise||'',dependency:choice.compromise||'',effect:0}};
 soloState={...soloState,capital:soloState.capital-ca,change:soloState.change-ch,activations:[...(soloState.activations||[]),activation],pendingCapability:null,pendingActivation:null,phase:'commitment-impact',history:[...(soloState.history||[]),'commitment']};
 saveSolo();soloRender();
}

function soloCommitment(){let c=soloCapability(soloState.pendingCapability),views=soloCommitmentOptions(c.id);soloShell(`${soloBars()}${arthurKey(needMap[c.id])}<div class="eyebrow">NOW DESIGN AROUND IT</div><h1>${E(designQuestions[c.id]||soloCommitmentQuestion(c.id))}</h1><p class="solo-lead design-prompt">Choose how this investment becomes part of Arthur’s environment.</p>${vitruviusLensHTML()}<div class="design-choice-grid">${views.map((x,index)=>{let v=plainDesignChoice(c.id,x,index);return `<article class="design-choice-card"><img src="${asset(v.image)}" alt="${E(v.title)}"><div class="design-choice-body"><h2>${E(v.title)}</h2><p class="design-choice-line">${E(v.line)}</p>${capabilityNeedTags(c.id)}<div class="design-consideration"><b>DESIGN CONSIDERATION</b><p>${E(v.consideration)}</p></div><button type="button" class="design-choice-button" data-capability-id="${E(c.id)}" data-design-index="${index}">CHOOSE THIS DESIGN</button></div></article>`}).join('')}</div><p id="designChoiceError" class="design-choice-error" hidden></p>`,{decision:true})}

function commitmentAha(capabilityId,choice){
 const title=plainDesignChoice(capabilityId,choice,soloCommitmentOptions(capabilityId).findIndex(x=>String(x.id)===String(choice?.id))).title;
 const messages={
  ambient:`${title} shows that a better discharge plan only matters if Arthur can understand, confirm and carry it forward.`,
  wayfinding:`${title} shows that updated directions only matter when Arthur can use them in the physical environment.`,
  meds:`${title} shows that finding a medication issue is different from resolving it for Arthur.`,
  command:`${title} shows that seeing a transition problem is different from having the capacity to respond.`
 };
 return messages[capabilityId]||'Technology creates possibility. Design determines what Arthur can actually rely on.'
}
