  function compiledPromptDebug(){let prompt=compileImagePrompt(soloState);return `<details class="prompt-debug"><summary>DEVELOPER VIEW · COMPILED IMAGE PROMPT</summary><pre>${E(prompt)}</pre><small>This is a structured preview only. No image model is connected in this build.</small></details>`}
  function soloCommitmentImpact(){let a=soloState.activations.at(-1),c=soloCapability(a.capabilityId),x=a.choice,v=plainDesignChoice(c.id,x,a.designIndex??0);if(a.capabilityId==='command'){soloShell(coordinatedResponseDesignHTML({choiceId:a.commitmentId,asset}),{complete:true,visual:false});bindCoordinatedResponseDesign(document,()=>soloSet('design'));return}if(a.capabilityId==='ambient'){soloShell(smartDischargeDesignHTML({choiceId:a.commitmentId,asset}),{complete:true,visual:false});bindSmartDischargeDesign(document,()=>soloSet('design'));return}if(a.capabilityId==='meds'){soloShell(medicationDesignRevealHTML({choiceId:a.commitmentId,asset}),{complete:true,visual:false});bindMedicationDesignReveal(document,()=>soloSet('design'));return}soloShell(`<div class="eyebrow">DECISION → IMPACT → AHA</div><h1>YOU DESIGNED ${E(v.title)}.</h1>${storyboardHTML(soloState,'design',asset)}${architectureRevealHTML(a)}<section class="impact-hero"><b>WHAT ARTHUR GAINS</b><h2>${E(x.benefit)}</h2></section><div class="impact-grid"><div><b>THE ENVIRONMENT NOW HAS TO</b><p>${E(soloCommitmentView(c.id,x))}</p></div><div><b>OPERATING REQUIREMENT</b><p>${E(a.architecture?.dependencies?.join(' ')||x.benefit)}</p></div><div><b>ACCEPTED VULNERABILITY</b><p>${E(a.architecture?.vulnerability||x.compromise)}</p></div><div><b>REMAINING CAPACITY</b><p>${soloState.capital} Capital · ${soloState.change} Change</p></div></div><blockquote class="micro-aha"><b>AHA</b><p>${E(commitmentAha(c.id,x))}</p></blockquote>${soloButton('soloNext','REVIEW YOUR DESIGN',()=>soloSet('design'))}`,{complete:true})}
function soloOperationsDecision(){let index=soloState.activations.length-1,a=soloState.activations[index],c=soloCapability(a.capabilityId),choices=soloOperations[c.id];soloShell(`<div class="eyebrow">OPERATIONS · YOUR DECISION</div><h1>WHAT HAS TO REMAIN TRUE FOR THIS DESIGN TO WORK?</h1><p class="solo-lead">The capability and experience are defined. Choose the operating commitment that keeps them usable when conditions change.</p><div class="solo-choice-list">${choices.map(o=>`<article class="solo-choice-card"><h2>${E(o.label)}</h2><div class="choice-grid"><p><b>WHAT IT PROTECTS</b><br>${E(o.benefit)}</p><p><b>WHAT YOU ACCEPT</b><br>${E(o.tradeoff)}</p><p><b>DEPENDENCY CREATED</b><br>${E(o.dependency)}</p></div><button type="button" data-operation="${o.id}">COMMIT TO THIS OPERATING MODEL</button></article>`).join('')}</div>`,{decision:true});document.querySelectorAll('[data-operation]').forEach(b=>b.onclick=()=>{let operation=choices.find(o=>o.id===b.dataset.operation);soloState.activations[index]={...a,operation};soloState.pendingOperation=operation.id;saveSolo();soloSet('operations-impact')})}
function soloOperationsImpact(){let a=soloState.activations.at(-1),c=soloCapability(a.capabilityId),o=a.operation;soloShell(`<div class="eyebrow">DECISION → IMPACT → AHA</div><h1>YOU MADE THE DESIGN OPERATIONAL.</h1>${storyboardHTML(soloState,'operations',asset)}<section class="impact-hero"><b>WHAT THIS PROTECTS FOR ARTHUR</b><h2>${E(o.benefit)}</h2></section><div class="impact-grid"><div><b>OPERATING COMMITMENT</b><p>${E(o.label)}</p></div><div><b>TRADEOFF</b><p>${E(o.tradeoff)}</p></div><div><b>DEPENDENCY CREATED</b><p>${E(o.dependency)}</p></div><div><b>CAPABILITY</b><p>${E(c.name)}</p></div></div><blockquote class="micro-aha"><b>AHA</b><p>${E(o.aha)}</p></blockquote>${soloButton('soloNext','SEE YOUR DESIGN SO FAR',()=>soloSet('design'))}`,{complete:true})}
function portfolioStateVisual(state,phase='design'){let smart=smartDischargePortfolioHTML(state,asset),response=coordinatedResponsePortfolioHTML(state,asset),med=medicationPortfolioVisualHTML(state,asset);return smart||response||med||storyboardHTML(state,phase,asset)}
function soloDesign(){let affordable=S().capabilities.some(k=>!soloState.activations.some(i=>i.capabilityId===k.id)&&soloCost(k.id)[0]<=soloState.capital&&soloCost(k.id)[1]<=soloState.change),first=soloState.activations.length===1;soloShell(`${soloBars()}<div class="eyebrow">YOUR ROUND 1 DESIGN</div><h1>DESIGN CAPABILITY + COMMITMENT</h1>${portfolioStateVisual(soloState,'design')}<div class="portfolio-summary">${soloState.activations.map(a=>`<article><h2>${E(soloCapability(a.capabilityId).name)}</h2><p><b>DESIGN</b><br>${E(a.choice.label)}</p><p><b>OPERATING COMMITMENT</b><br>${E(a.operation?.description||soloCommitmentView(a.capabilityId,a.choice))}</p><p><b>ARTHUR GAINS</b><br>${E(a.choice.benefit)}</p><p><b>TRADEOFF</b><br>${E(a.choice.compromise)}</p></article>`).join('')}</div><div class="callout">The design capability creates possibility. The built environment and operating commitment make it usable under pressure.</div>${first?`<div class="eyebrow">YOUR SECOND INVESTMENT</div><h2>GO DEEPER OR GO BROADER?</h2><div class="depth-breadth"><article><h3>STRENGTHEN THIS DESIGN</h3><p>${E(strengthenCopy(soloState.activations[0]))}</p><p class="response-environment">Add backup support and improve the existing intervention points so they can accommodate changing plans.</p><button type="button" id="soloStrengthen" ${soloState.capital<1||soloState.change<1?'disabled':''}>STRENGTHEN · 1 CAPITAL + 1 CHANGE</button></article><article><h3>EXTEND THE JOURNEY</h3><p>Add another AI capability and integrate its spatial requirements into the environment you have already designed.</p><button type="button" id="soloExtend" ${!affordable?'disabled':''}>EXTEND WITH ANOTHER CAPABILITY</button></article></div>`:`<div class="storyline">TWO CAPABILITIES ACTIVATED · PORTFOLIO COMPLETE</div>`}<div class="solo-actions">${soloButton('soloProceed','PROCEED WITH THIS DESIGN',()=>soloSet('event'))}</div>`,{complete:true});if(q('#soloStrengthen'))q('#soloStrengthen').onclick=()=>{soloState=strengthenCurrent(soloState);saveSolo();soloSet('event')};if(q('#soloExtend'))q('#soloExtend').onclick=()=>{soloState=extendJourney(soloState);saveSolo();soloSet('capability')}}
const leaveWellEvents=[
 {id:'route',label:'ROUTE CHANGED',headline:'ARTHUR’S PLANNED PATH HOME NO LONGER WORKS.',story:'The east elevator closes. Transportation is waiting, and Arthur has the original route.',pressure:['MOVE','TRUST']},
 {id:'information',label:'PLAN CHANGED',headline:'ARTHUR’S PLAN CHANGES JUST BEFORE DEPARTURE.',story:'A medication changes and the follow-up appointment moves. Arthur now has two versions of the plan.',pressure:['UNDERSTAND','CONNECT']},
 {id:'coordination',label:'HANDOFF CHANGED',headline:'ARTHUR’S HANDOFF STARTS TO BREAK.',story:'Transportation arrives early, the family contact is unavailable, and the receiving team has the original plan.',pressure:['CONNECT','TRUST']}
];
function currentLeaveWellEvent(){const forced=qs.get('event');if(['route','information','coordination'].includes(forced)&&soloState.eventId!==forced){soloState.eventId=forced;soloState.eventSeed=leaveWellEvents.findIndex(x=>x.id===forced);saveSolo()}let e=leaveWellEvents.find(x=>x.id===soloState.eventId);if(!e){let seed=soloState.eventSeed??Math.floor(Math.random()*leaveWellEvents.length);soloState.eventSeed=seed;e=leaveWellEvents[seed%leaveWellEvents.length];soloState.eventId=e.id;saveSolo()}return e}
