function soloActivationEvidence(a){let c=soloCapability(a.capabilityId),x=a.choice;return{capability:c.name,commitment:x.label,outcome:x.outcome||'STRAINED',arthur:x.arthur||x.benefit,held:x.held||x.benefit,gap:x.failed||x.compromise,aha:x.aha||'Technology created possibility. Design shaped the experience.'}}
function soloPortfolioEvaluation(state=soloState){let event=currentLeaveWellEvent(),responseId=state.response||'use',result=evaluatePortfolio({...state,eventId:event.id},event.id,responseId);return{...result,event:{...event,...result.event},evidence:result.effects.map(e=>({capability:playerName(e.activation.capabilityId),commitment:e.title,arthur:e.causal,blocked:e.blocked})),responseWhy:result.response.why,sameTechAha:`${event.label} pressured ${event.pressure.join(' and ')}. The AI-powered option created possibility; the design and operating readiness determined what Arthur could actually rely on.`}}

function soloEvent(){let e=currentLeaveWellEvent();soloShell(`<div class="eyebrow">CONDITIONS CHANGED · ${E(e.label)}</div><h1>${E(e.headline)}</h1><p class="solo-lead">${E(e.story)}</p><p class="physical-challenge">Arthur is approaching the departure point. Arthur needs somewhere safe to pause, a way to understand the new plan and someone or something able to move the transition forward.</p>${arthurKey(e.pressure)}<h2>WILL YOUR DESIGN HOLD?</h2><div class="solo-predict"><button data-predict="YES">YES</button><button data-predict="NOT SURE">NOT SURE</button><button data-predict="NO">NO</button></div>`,{decision:true});document.querySelectorAll('[data-predict]').forEach(b=>b.onclick=()=>{soloState.prediction=b.dataset.predict;saveSolo();soloGo('pressure')})}

function applyResponseTransaction(option){
 const previous=soloState.responseTransaction;
 if(previous?.applied&&previous.eventId===soloState.eventId&&previous.responseId===option.id)return true;
 let capital=soloState.capital,change=soloState.change;
 if(previous?.applied&&previous.eventId===soloState.eventId){capital+=previous.capitalCharged||0;change+=previous.changeCharged||0}
 if(option.cost[0]>capital||option.cost[1]>change)return false;
 soloState.capital=capital-option.cost[0];soloState.change=change-option.cost[1];
 soloState.response=option.id;soloState.responseCost={capital:option.cost[0],change:option.cost[1]};
 soloState.responseTransaction={eventId:soloState.eventId,responseId:option.id,capitalCharged:option.cost[0],changeCharged:option.cost[1],applied:true};
 return true
}
function soloPressure(){let e=currentLeaveWellEvent(),cards=universalResponses.map(o=>{let eligibility=responseEligibility({...soloState,eventId:e.id},o.id,e.id),disabled=o.cost[0]>soloState.capital||o.cost[1]>soloState.change||!eligibility.eligible,cost=o.cost[0]+o.cost[1]===0?'NO EXTRA COST':`◆ ${o.cost[0]} · ● ${o.cost[1]}`;return`<article><h2>${E(o.label)}</h2><p>${E(o.copy)}</p><small>${E(cost)}</small><span class="response-environment">${E(responseEnvironmentCopy(o.id))}</span><span class="response-condition">${E(eligibility.why)}</span><button data-response="${o.id}" ${disabled?'disabled':''}>${eligibility.eligible?'CHOOSE':'NOT AVAILABLE'}</button></article>`}).join('');soloShell(`${soloBars()}<div class="eyebrow">RESPOND · ${E(e.label)}</div><h1>HOW WILL THE TEAM RESPOND?</h1><div class="pressure-options">${cards}</div>`,{decision:true});document.querySelectorAll('[data-response]').forEach(b=>b.onclick=()=>{let o=universalResponses.find(x=>x.id===b.dataset.response),eligibility=responseEligibility({...soloState,eventId:e.id},o?.id,e.id);if(!o||!eligibility.eligible||!applyResponseTransaction(o))return;saveSolo();soloGo('consequence')})}

function revisionComparisonHTML(current){let prior=soloState.comparison?.previousEvaluation;if(!prior)return'';let comparison=compareEvaluations(prior,current),kept=soloState.comparison?.previousResponse||'use',eligibility=responseEligibility({...soloState,eventId:current.event?.id},kept,current.event?.id),invalid=kept!=='use'&&!eligibility.eligible;return`<section class="revision-compare"><article><span>BEFORE</span><h3>${E(prior.outcome)}</h3><p>${E(prior.causalSummary?.join(' ')||'')}</p></article><article class="after"><span>AFTER</span><h3>${E(current.outcome)}</h3>${invalid?`<p class="blocked">${E(kept.toUpperCase())} UNAVAILABLE UNDER REVISED DESIGN · ${E(eligibility.why)}</p>`:''}<p>${E(current.causalSummary?.join(' ')||'')}</p><strong>${E(comparison.summary)}</strong></article></section>`}
function soloConsequence(){let r=soloPortfolioEvaluation(),causal=r.effects.map(e=>`<article class="causal-card"><h3>${E(playerName(e.activation.capabilityId))} · ${E(e.title)}</h3><p>${E(e.causal)}</p>${e.blocked?`<p class="blocked">MISSING PREREQUISITE · ${E(e.blocked)}</p>`:''}</article>`).join('');soloShell(`<div class="eyebrow">${E(r.event.label)} · ARTHUR EXPERIENCES THE DESIGN</div><h1>${E(r.outcome)}</h1>${portfolioStateVisual(soloState,'outcome')}${revisionComparisonHTML(r)}<section class="four-need-score">${Object.entries(r.scores).map(([k,v])=>`<div class="${r.event.pressure.includes(k)?'pressured':''}"><b>${k}</b><span>${'●'.repeat(Math.min(3,v))}${'○'.repeat(Math.max(0,3-v))}</span></div>`).join('')}</section><section class="response-explanation"><b>WHY THIS RESPONSE DID OR DID NOT HELP</b><p>${E(r.responseWhy)}</p></section><section class="causal-grid"><h2>WHAT EACH DECISION CHANGED</h2>${causal}</section>${architectureAssessmentHTML(r)}<blockquote class="aha-block"><b>DESIGN INSIGHT</b><p>${E(r.sameTechAha)}</p></blockquote><div class="solo-actions">${soloButton('soloTry','TRY ONE DIFFERENT DESIGN',()=>soloStartRevision(),true)}${soloButton('soloNext','WHAT DID WE LEARN?',()=>soloGo('principle'))}</div>`,{complete:true})}

function soloStartRevision(){let prior=soloPortfolioEvaluation();soloState.comparison={previousEvaluation:prior,previousOutcome:prior.outcome,previousResponse:soloState.response,previousScores:prior.scores,previousEvent:prior.event?.id,previousActivations:structuredClone(soloState.activations),previousResources:{capital:soloState.capital,change:soloState.change}};if(soloState.activations.length===1){soloState.reviseIndex=0;saveSolo();soloGo('revise')}else{saveSolo();soloGo('choose-revision')}}
function soloChooseRevision(){soloShell(`<div class="eyebrow">CHANGE ONE VARIABLE</div><h1>WHICH DESIGN WILL YOU REVISIT?</h1><p>Everything else will stay the same so you can see what the design decision changes for Arthur.</p><div class="solo-choice-list">${soloState.activations.map((a,i)=>`<article class="solo-choice-card"><h2>${E(soloCapability(a.capabilityId).name)}</h2><h3>${E(a.choice.label)}</h3><button type="button" data-revise-index="${i}">REVISE THIS DESIGN</button></article>`).join('')}</div>`,{decision:true});document.querySelectorAll('[data-revise-index]').forEach(b=>b.onclick=()=>{soloState.reviseIndex=Number(b.dataset.reviseIndex);saveSolo();soloGo('revise')})}
function soloRevise(){let a=soloState.activations[soloState.reviseIndex],c=soloCapability(a.capabilityId);soloShell(`<div class="eyebrow">SAME ARTHUR · SAME CAPABILITY · SAME DISRUPTION · SAME RESPONSE</div><h1>CHANGE ONE DESIGN DECISION.</h1><p>Current design: <b>${E(a.choice.label)}</b></p><div class="solo-choice-list">${c.choices.filter(x=>x.id!==a.commitmentId).map(x=>`<article class="solo-choice-card"><h2>${E(x.label)}</h2><div class="choice-grid"><p><b>WHAT ARTHUR GAINS</b><br>${E(x.benefit)}</p><p><b>WHAT YOU COMMIT TO</b><br>${E(soloCommitmentView(c.id,x))}</p><p><b>WHAT MIGHT BREAK</b><br>${E(x.compromise)}</p></div><button type="button" data-new-design="${x.id}">TRY THIS DESIGN</button></article>`).join('')}</div>`,{decision:true});document.querySelectorAll('[data-new-design]').forEach(b=>b.onclick=()=>{let x=c.choices.find(v=>v.id===b.dataset.newDesign),keptResponse=soloState.comparison?.previousResponse||soloState.response||'use';soloState.activations[soloState.reviseIndex]={...a,commitmentId:x.id,choice:x,architecture:architectureChoice(c.id,x.id)};soloState.response=keptResponse;saveSolo();soloGo('consequence')})}

function finalDesignDiagnosis(){let r=soloPortfolioEvaluation(),acts=soloState.activations||[],response=universalResponses.find(x=>x.id===soloState.response)||universalResponses[0],names=acts.map(a=>playerName(a.capabilityId)),designs=r.effects.map(e=>e.title),strongest=[...r.effects].sort((a,b)=>b.fit-a.fit)[0],whatHeld=strongest?.fit>=.55?strongest.causal:`Your investments supported Arthur, but none directly resolved ${r.event.label.toLowerCase()}.`,whatDidnt=r.vulnerabilities.length?`${r.vulnerabilities.join(' + ')} remained most exposed. ${r.effects.filter(e=>e.blocked).map(e=>`Missing ${e.blocked}.`).join(' ')}`:'Arthur’s four Leave Well needs were broadly covered, while the remaining operating dependencies still mattered.',spent=soloState.responseTransaction?.applied?`${soloState.responseTransaction.capitalCharged?`◆ ${soloState.responseTransaction.capitalCharged} Capital`:''}${soloState.responseTransaction.capitalCharged&&soloState.responseTransaction.changeCharged?' + ':''}${soloState.responseTransaction.changeCharged?`● ${soloState.responseTransaction.changeCharged} Change`:''}`:'No additional resources',subtype=r.outcome==='STRAINED'?(soloState.response==='use'?'DEPENDENT':'RECOVERED'):'';return{...r,names,designs,whatHeld,whatDidnt,spent,subtype,responseLabel:response.label}}
function soloPrinciple(){let d=finalDesignDiagnosis();soloShell(`<div class="eyebrow">LEAVE WELL · YOUR DESIGN RESULT</div><h1>THIS IS WHAT YOU DESIGNED.</h1>${portfolioStateVisual(soloState,'outcome')}<div class="result-design-line"><div><span>AI-POWERED OPTION${d.names.length>1?'S':''}</span><b>${E(d.names.join(' + '))}</b></div><div><span>YOUR DESIGN</span><b>${E(d.designs.join(' + '))}</b></div></div><div class="result-insights"><article class="held"><span>WHAT HELD</span><p>${E(d.whatHeld)}</p></article><article class="gap"><span>WHAT REMAINED VULNERABLE</span><p>${E(d.whatDidnt)}</p></article><article class="cost"><span>WHAT IT TOOK</span><p>${E(d.responseLabel)} · ${E(d.spent)}</p></article></div><div class="result-outcome"><span>LEAVE WELL RESULT</span><strong>${E(d.outcome)}${d.subtype?` · ${E(d.subtype)}`:''}</strong></div><p class="result-diagnosis">${d.outcome==='ABSORBED'?'Arthur’s transition absorbed the change using the design you created.':d.outcome==='STRAINED'?(d.subtype==='RECOVERED'?'Arthur completed the transition, but your team had to use additional capacity to recover.':'Arthur completed the transition, but the design remained dependent on support outside the environment.'):'The disruption exposed a need Arthur could not reliably meet with the design and response available.'}</p><details class="learn-more final-learn-more"><summary>SEE THE DESIGN PRINCIPLES</summary><div class="principle-column"><article><span>UTILITAS</span><h2>USEFUL</h2><p>Did the design work for Arthur?</p></article><article><span>FIRMITAS</span><h2>RESILIENT</h2><p>Did it hold when conditions changed?</p></article><article><span>VENUSTAS</span><h2>HUMAN</h2><p>Did Arthur keep dignity, confidence and agency?</p></article></div></details>${architecturalObligationsHTML(d)}<div class="opening-return"><span>YOU STARTED HERE</span><blockquote>${E(soloState.openingResponse||'Arthur needs a transition that works beyond the hospital.')}</blockquote><p>Your playthrough tested that instinct against a changing handoff. The final design shows where the environment can work harder when the original plan breaks.</p></div>${compiledPromptDebug()}<blockquote class="final-thesis"><b>AI CHANGED WHAT THE HOSPITAL COULD DO.</b><br><b>ARCHITECTURE MADE IT USEFUL, RESILIENT AND HUMAN.</b></blockquote>${soloButton('soloRestartRound','REPLAY LEAVE WELL',()=>soloReset())}`,{complete:true})}

function soloRender(){if(!Array.isArray(soloState.activations))soloState.activations=[];if(soloState.phase==='operations'||soloState.phase==='operations-impact'){let a=soloState.activations.at(-1);if(a&&!a.operation)a.operation={id:'embedded',label:'Embedded operating commitment',description:soloCommitmentView(a.capabilityId,a.choice),dependency:a.choice.compromise,effect:0};soloState.phase='design';saveSolo()}switch(soloState.phase){case'meet':return soloMeet();case'opening-question':return soloOpeningQuestion();case'opening-cloud':return soloOpeningCloud();case'journey':return soloJourney();case'needs':return soloNeeds();case'rules':return soloRules();case'capability-intro':return soloCapabilityIntro();case'card-guide':return soloCardGuide();case'capability':return soloCapabilities();case'activation-impact':return soloActivationImpact();case'commitment':return soloCommitment();case'commitment-impact':return soloCommitmentImpact();case'design':return soloDesign();case'event':return soloEvent();case'pressure':return soloPressure();case'consequence':return soloConsequence();case'choose-revision':return soloChooseRevision();case'revise':return soloRevise();case'principle':return soloPrinciple();default:soloReset()}}
function solo(){loadSolo();soloRender()}

if(mode==='facilitator')facilitator();else if(mode==='player')player();else if(mode==='solo-register')soloRegistration();else if(mode==='solo')solo();else start()
